{
  "title": "探秘烛龙之眼",
  "scene": "在一片被晨雾笼罩的山林中，你会看到一座古老的石碑，上面刻着“烛龙之眼”的字样。周围生长着各种奇花异草，空气中弥漫着淡淡的药香。据传，烛龙之眼是能洞察万物、指引迷途的宝物，但保护它的怪物也异常凶猛。",
  "goal": "收集烛龙之眼，解开石碑上的谜题，找到通往下一个秘境的入口。",
  "choices": [
    {
      "id": "A",
      "text": "使用随身携带的草药试图安抚周围的怪兽",
      "outcome": "怪兽似乎被草药的香气吸引，暂时放松警惕，玩家可以安全接近石碑。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "尝试直接使用武力解决怪兽",
      "outcome": "怪兽受到了惊吓，变得更加暴躁，它们攻击了玩家。玩家受伤，但成功逃脱了怪兽的视线。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "避开怪兽，寻找其他方法接近石碑",
      "outcome": "玩家发现了一条隐蔽的小径，通过这条小径悄然接近了石碑。但是，小径尽头却出现了更多的怪兽。",
      "result": "fail",
      "next": "bad_end"
    }
  ]
}
